{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
<link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
<div class="site-bg"></div>
<header class="site-header">
  <div class="container">
    <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
    <nav class="nav">
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html">Reach</a>
    </nav>
  </div>
</header>

<main>
<section class="hero">
  <div class="container hero-inner">
    <h1 class="title">{{TAGLINE}}</h1>
    <p class="subtitle">A membership for steady habits, practical frameworks, and daily micro-choices that build lasting routines.</p>
    <div class="hero-actions">
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a class="btn secondary" href="about.html">Meet the Coach</a>
    </div>
    <svg class="hero-pattern" width="200" height="120"><use href="assets/img/pattern.svg#pattern"/></svg>
  </div>
</section>

<section class="social-proof">
  <div class="container">
    <h2>Proof Gallery</h2>
    <div class="gallery">
      <div class="testimonials" id="testimonials">
        <blockquote class="quote">"This membership helped me create a 10-minute evening routine that stuck."</blockquote>
        <cite class="author">— Participant A</cite>
      </div>
      <div class="badges" id="badges">
        <span class="badge" data-tip="Published features: Mindful Living">Mindful</span>
        <span class="badge" data-tip="Rated 4.9 by members">Top-rated</span>
        <span class="badge" data-tip="Community-run cohorts">Peer-led</span>
      </div>
    </div>
  </div>
</section>

<section class="benefits">
  <div class="container">
    <h2>Outcomes you will build</h2>
    <ul class="benefit-list">
      <li><strong>Practical habits</strong> — daily micro-commitments that anchor your routine.</li>
      <li><strong>Simple frameworks</strong> — repeatable processes for mornings, afternoons, and evenings.</li>
      <li><strong>Accountability loop</strong> — weekly checkpoints and community reflections.</li>
    </ul>
  </div>
</section>

<section class="process">
  <div class="container">
    <h2>Your 30-day path map</h2>
    <p>Select the areas you want to focus on, then map a simple 30-day progression.</p>
    <form id="goalForm">
      <label><input type="checkbox" name="goals" value="sleep"> Improve sleep consistency</label>
      <label><input type="checkbox" name="goals" value="energy"> Steadier energy across the day</label>
      <label><input type="checkbox" name="goals" value="movement"> Habit for regular movement</label>
      <label><input type="checkbox" name="goals" value="focus"> Better focus windows</label>
      <div class="form-row">
        <label>Intensity: <select id="intensity"><option value="low">Low</option><option value="med" selected>Moderate</option><option value="high">Ambitious</option></select></label>
        <button type="button" id="mapBtn" class="btn">Map my 30 days</button>
      </div>
    </form>
    <div class="path-map" id="pathMap" aria-hidden="true">
      <!-- SVG rendered here -->
    </div>
    <div class="day-list" id="dayList"></div>
  </div>
</section>

<section class="faq">
  <div class="container">
    <h2>Common questions</h2>
    <details><summary>Is this a medical program?</summary><p>No. This membership focuses on habits, routines, and coaching frameworks—not medical advice.</p></details>
    <details><summary>How often are live sessions?</summary><p>Monthly group workshops, weekly check-ins in the member hub, and optional one-on-one sessions.</p></details>
    <details><summary>How do I cancel?</summary><p>Cancel anytime through your account. No long-term lock-ins.</p></details>
  </div>
</section>

<section class="cta">
  <div class="container">
    <h2>Start shaping your next month</h2>
    <p>Join a membership designed to layer small, daily moves into steady change.</p>
    <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    <p class="muted">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
  </div>
</section>

</main>

<footer class="site-footer">
  <div class="container">
    <small>&copy; {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}. All rights reserved.</small>
    <nav class="foot-nav">
      <a href="privacy.html">Privacy</a><a href="terms.html">Terms</a>
    </nav>
  </div>
</footer>

<script src="assets/js/main.js"></script>
</body>
</html>"} 
