{"path":"assets/css/styles.css","content":"/* Glass morphism wellness coach styles */
:root{
  --bg:#0f1724;
  --glass:rgba(255,255,255,0.06);
  --glass-2:rgba(255,255,255,0.04);
  --accent:#7bd389;
  --muted:#b7c1c7;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial;line-height:1.45;background:linear-gradient(180deg,#08101a 0%,#0f1724 100%);color:#e6eef6;margin:0}
.site-bg{position:fixed;inset:0;background-image:url('../assets/img/pattern.svg');opacity:0.06;mix-blend-mode:screen;pointer-events:none}
.container{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{backdrop-filter:blur(8px);background:linear-gradient(180deg,var(--glass),transparent);border-bottom:1px solid rgba(255,255,255,0.03);position:sticky;top:0;z-index:50}
.site-header .container{display:flex;align-items:center;gap:1rem}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.15rem}
.nav{margin-left:auto;display:flex;gap:0.75rem;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:0.6rem 0.8rem;border-radius:6px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),#5ee0b1);color:#03201a;font-weight:600}
.hero{padding:4rem 0}
.hero-inner{display:grid;grid-template-columns:1fr 220px;gap:1.5rem;align-items:center}
.title{margin:0;font-size:1.9rem;color:#dff8ea}
.subtitle{color:var(--muted);margin:0.5rem 0 1rem}
.hero-actions{display:flex;gap:0.75rem}
.btn{display:inline-block;padding:0.7rem 1rem;border-radius:10px;text-decoration:none;border:1px solid rgba(255,255,255,0.06);cursor:pointer}
.btn.primary{background:linear-gradient(90deg,var(--accent),#5ee0b1);color:#04201a;font-weight:700}
.btn.secondary{background:transparent;color:var(--muted)}
.btn.large{padding:1rem 1.2rem;font-size:1.05rem}
.hero-pattern{opacity:0.6}
.social-proof{padding:2.5rem 0}
.gallery{display:flex;gap:1.25rem;align-items:center;flex-wrap:wrap}
.testimonials{flex:1;min-width:260px;background:linear-gradient(180deg,var(--glass-2),transparent);padding:1rem;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.quote{font-style:italic;margin:0 0 0.5rem;color:#f5fff9}
.author{color:var(--muted);font-size:0.9rem}
.badges{display:flex;gap:0.5rem}
.badge{background:rgba(255,255,255,0.03);padding:0.4rem 0.6rem;border-radius:8px;font-weight:600;color:var(--muted);cursor:default;position:relative}
.badge:hover{background:rgba(255,255,255,0.06)}
.badge[data-tip]:hover:after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#041117;color:#e6fdf3;padding:0.4rem 0.6rem;border-radius:6px;white-space:nowrap;font-size:0.85rem;box-shadow:0 6px 18px rgba(2,6,8,0.6)}
.benefits{padding:2rem 0}
.benefit-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;list-style:none;padding:0;margin:0}
.process{padding:2.5rem 0}
form#goalForm{display:flex;flex-direction:column;gap:0.5rem}
form#goalForm label{display:block;color:var(--muted)}
.form-row{display:flex;gap:0.75rem;align-items:center;margin-top:0.5rem}
.path-map{margin-top:1rem;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:0.75rem;border-radius:10px}
.path-map svg{width:100%;height:120px}
.day-list{margin-top:0.8rem;color:var(--muted);font-size:0.95rem}
.day-item{padding:0.35rem 0;border-bottom:1px dashed rgba(255,255,255,0.02)}
.faq{padding:2rem 0}
.cta{padding:2.5rem 0;text-align:center}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:1.25rem 0;margin-top:2rem}
.site-footer .container{display:flex;justify-content:space-between;align-items:center}
.foot-nav a{color:var(--muted);text-decoration:none;margin-left:0.75rem}
@media(max-width:800px){
  .hero-inner{grid-template-columns:1fr}
  .nav{display:none}
}
/* Path node styles */
.node{fill:#0b2a20;stroke:rgba(255,255,255,0.06);}
.node.active{fill:var(--accent);stroke:#0b2a20}
.connector{stroke:rgba(255,255,255,0.04);stroke-width:2}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Testimonials rotation and badge tooltips
  const testimonials = [
    {text:'"I learned how to shape a weekly plan that actually fits my life."', author:'— Member S.'},
    {text:'"Small prompts and shared check-ins kept me consistent for months."', author:'— Member L.'},
    {text:'"The frameworks uncluttered my mornings and gave me reliable focus time."', author:'— Member R.'}
  ];
  let ti = 0;
  const tEl = document.getElementById('testimonials');
  function showTestimonial(i){
    if(!tEl) return;
    tEl.innerHTML = '<blockquote class="quote">'+testimonials[i].text+'</blockquote><cite class="author">'+testimonials[i].author+'</cite>';
  }
  showTestimonial(0);
  setInterval(()=>{ti=(ti+1)%testimonials.length;showTestimonial(ti);},4500);

  // Path map generator
  const mapBtn = document.getElementById('mapBtn');
  const pathMap = document.getElementById('pathMap');
  const dayList = document.getElementById('dayList');
  function makePlan(goals,intensity){
    const days = 30;
    // heuristics for difficulty
    const effort = intensity==='low'?0.5: intensity==='med'?1:1.5;
    // baseline micro-tasks by goal
    const goalTasks = {
      sleep: ['bedtime wind-down','consistent sleep window','no screens 30m before bed'],
      energy: ['midday reset','hydration check','mini-walk or stretch'],
      movement: ['10-minute movement','short walk','mobility set'],
      focus: ['deep work block','single-task stretch','task batch']
    };
    // build day items
    const items = [];
    for(let d=1; d<=days; d++){
      const day = {day:d,items:[]};
      goals.forEach(g=>{
        // pick a task based on day and effort
        const list = goalTasks[g]||[];
        const pick = list[(d-1)%list.length] || 'small practice';
        // scale intensity: every nth day add micro-challenge
        const challenge = (d % Math.max(1,Math.round(7/effort)) ===0) ? 'plus: small challenge' : '';
        day.items.push(pick + (challenge?(' — '+challenge):''));
      });
      // if no goals selected, give a gentle default
      if(goals.length===0){
        day.items.push(d%3? 'micro-check: morning set':'micro-check: evening reflect');
      }
      items.push(day);
    }
    return items;
  }

  function renderMap(plan){
    // create an SVG with 30 nodes in a sine path for visual interest
    const days = plan.length;
    const w = Math.max(800, window.innerWidth-80);
    const h = 120;
    const padding = 24;
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS,'svg');
    svg.setAttribute('width','100%');
    svg.setAttribute('viewBox','0 0 '+w+' '+h);
    // create path points
    const points = [];
    for(let i=0;i<days;i++){
      const x = padding + (i*(w-2*padding)/(days-1));
      const y = h/2 + Math.sin(i/3)*20;
      points.push({x,y});
    }
    // connectors
    for(let i=0;i<days-1;i++){
      const line = document.createElementNS(svgNS,'line');
      line.setAttribute('x1',points[i].x);
      line.setAttribute('y1',points[i].y);
      line.setAttribute('x2',points[i+1].x);
      line.setAttribute('y2',points[i+1].y);
      line.setAttribute('class','connector');
      svg.appendChild(line);
    }
    // nodes
    points.forEach((p,idx)=>{
      const circle = document.createElementNS(svgNS,'circle');
      circle.setAttribute('cx',p.x);
      circle.setAttribute('cy',p.y);
      circle.setAttribute('r',8);
      circle.setAttribute('class','node');
      circle.setAttribute('data-day',idx+1);
      circle.style.cursor='pointer';
      circle.addEventListener('click',()=>{
        // toggle complete
        circle.classList.toggle('active');
        const key = 'wellness_plan_progress';
        const stored = JSON.parse(localStorage.getItem(key)||'{}');
        stored['d'+(idx+1)] = circle.classList.contains('active');
        localStorage.setItem(key,JSON.stringify(stored));
        updateDayList(plan);
      });
      svg.appendChild(circle);
    });
    pathMap.innerHTML='';
    pathMap.appendChild(svg);
    pathMap.setAttribute('aria-hidden','false');
    updateDayList(plan);
  }

  function updateDayList(plan){
    const key='wellness_plan_progress';
    const stored = JSON.parse(localStorage.getItem(key)||'{}');
    const lines = plan.map(d=>{
      const done = stored['d'+d.day] ? '✓ ' : '';
      const text = d.items.join(' • ');
      return '<div class="day-item"><strong>Day '+d.day+'</strong>: '+done+text+'</div>';
    });
    dayList.innerHTML = lines.join('');
    // update nodes from storage
    const circles = document.querySelectorAll('.path-map svg circle');
    circles.forEach(c=>{
      const n = 'd'+c.getAttribute('data-day');
      if(stored[n]) c.classList.add('active'); else c.classList.remove('active');
    });
  }

  if(mapBtn){
    mapBtn.addEventListener('click',()=>{
      const checked = Array.from(document.querySelectorAll('input[name="goals"]:checked')).map(i=>i.value);
      const intensity = document.getElementById('intensity').value;
      const plan = makePlan(checked,intensity);
      renderMap(plan);
    });
  }

  // accessibility: seed an example plan for first time visitors
  document.addEventListener('DOMContentLoaded',()=>{
    const seeded = localStorage.getItem('wellness_plan_seeded');
    if(!seeded){
      const plan = makePlan(['sleep','energy'],'med');
      renderMap(plan);
      localStorage.setItem('wellness_plan_seeded','1');
    }
  });

  // Small interactive: allow pressing numbers 1-9 to toggle correspond node
  document.addEventListener('keydown',(e)=>{
    const n = parseInt(e.key,10);
    if(n>=1 && n<=9){
      const circle = document.querySelector('.path-map svg circle[data-day="'+n+'"]');
      if(circle) circle.click();
    }
  });
})();"} 
